import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let e: List<Int64> = []

    let c = e.iterator().count()
    if c == 0 { io.println("count-ok") } else { io.println("count-bad") }

    let a = e.iterator().any(|x| x > 0)
    if a { io.println("any-bad") } else { io.println("any-ok") }

    let b = e.iterator().all(|x| x > 0)
    if b { io.println("all-ok") } else { io.println("all-bad") }

    let s = e.iterator().fold(7, |acc, x| acc + x)
    if s == 7 { io.println("fold-ok") } else { io.println("fold-bad") }

    let r = e.iterator().reduce(|p, q| p + q)
    match r {
        Some(v) => { io.println("reduce-some-bad") }
        None => { io.println("reduce-none-ok") }
    }

    let f = e.iterator().find(|x| x > 0)
    match f {
        Some(v) => { io.println("find-some-bad") }
        None => { io.println("find-none-ok") }
    }

    return Ok(())
}
